$m['lines'][]=resourceLine('write','storage.block.write','3','storage-fixture',1,1048576,1,1024);
ResourceManifest::validate($m,$catalog,$cap,0);
$c=['id'=>str_repeat('b',64),'request_id'=>str_repeat('c',64),'usage_assignment_generation'=>str_repeat('d',64),'resource_manifest'=>$m,'resource_capability'=>$cap,'hosted'=>null,'funded_height'=>1,'end_height'=>100];
