$scope=['chain'=>'local-meter-test','genesis'=>$genesis,'provider_id'=>$cap['provider_id'],'workload_id'=>$c['request_id'],'assignment_generation'=>$c['usage_assignment_generation'],'commitment'=>$c['id'],'interval_start_height'=>1,'interval_end_height'=>100,'catalog_hash'=>$p['catalog_hash'],'manifest_hash'=>ResourceManifest::hash($m)];
