try{
 $meter=new MeteringService($dir);$meter->bind($scope);$meter->begin($c['id'],$sample(10,1000,[]));
 $meter->checkpoint($c['id'],$sample(100,1200,['8:0'=>$zero]));
 rejects(fn()=>$meter->checkpoint($c['id'],$sample(101,1100,['8:0'=>$zero])),'Monotonic regression rejected');
 $changed=$sample(101,1300,['8:0'=>$zero]);$changed['memory_limit_bytes']='8388608';
 rejects(fn()=>$meter->checkpoint($c['id'],$changed),'Mid-interval RAM limit changes rejected');
 $missing=$sample(101,1300,['8:0'=>$zero]);unset($missing['monotonic_ms']);
 rejects(fn()=>$meter->checkpoint($c['id'],$missing),'Timestamp removal rejected');
