 $candidate=$prepare($bundle);$e=$candidate['evidence'];
 check(array_column($e['measurements'],'quantity')===['750','4000','2048','4096'],'CPU, RAM reservation, read/write quantities derive from persisted counters');
 check(!$candidate['payable']&&$candidate['verification_level']==='C'&&$candidate['signing_required'],'Candidate does not grant payment or independent trust');
 check($e['measurement_start_ms']==='1000'&&$e['measurement_end_ms']==='2000','Raw monotonic measurement window retained');
