 rejects(fn()=>$prepare($bundle,null,[]),'Unmapped block device rejected');
 rejects(fn()=>$prepare($bundle,null,[str_repeat('3',64)=>'8:0',str_repeat('4',64)=>'8:0']),'Aliased block counters cannot double bill assets');
 rejects(fn()=>$prepare($bundle,null,[str_repeat('3',64)=>'8:1']),'Missing device is not fabricated zero usage');
 $rehash=static function($b){$b['evidence_bundle_hash']=bin2hex(\Greenwood\Crypto\ProtocolHash::hash('GREENWOOD_LOCAL_METER_BUNDLE_V1',CanonicalJson::encode($b['bundle'])));return $b;};
 $bad=$bundle;$bad['bundle']['boundary_reconciliation_required']=true;rejects(fn()=>$prepare($rehash($bad)),'Uncertain polling boundary cannot become a bill');
 $bad=$bundle;$bad['bundle']['segments'][0]['last']['io_devices']=null;rejects(fn()=>$prepare($rehash($bad)),'Unavailable block controller is not zero');
 $bad=$bundle;$bad['bundle']['segments'][0]['first']['monotonic_ms']='2000';rejects(fn()=>$prepare($rehash($bad)),'Zero duration rejected');
 $bad=$bundle;$bad['bundle']['segments'][0]['last']['memory_limit_bytes']='8388608';rejects(fn()=>$prepare($rehash($bad)),'Reservation cannot use an unrelated hard memory limit');
 echo json_encode(['status'=>'PASS','checks'=>$checks,'actual_sqlite'=>true,'counter_inputs'=>'SYNTHETIC_FIXTURES','physical_qualification'=>false],JSON_PRETTY_PRINT)."\n";
}finally{unset($meter);foreach(glob($dir.'/*')?:[] as $file)unlink($file);if(is_dir($dir))rmdir($dir);}
